--region lifecycle
function StoreGiftCell:__init()
    self._cellData = nil
    self._tickHandler = nil
end

function StoreGiftCell:__delete()
    self._cellData = nil
    self._tickHandler = nil
end

function StoreGiftCell:Awake()
    SetButtonAction(self.obj, Bind(self, self.CellClickHandler))
end

